CREATE SCHEMA "app";


SET default_tablespace = '';

SET default_table_access_method = "heap";

--
-- Name: visits; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE "app"."visits" (
    "chair_id" bigint,
    "doctor_id" bigint,
    "visit_type" "text",
    "visit_date" timestamp with time zone,
    "accompanied_by" "text",
    "load_date" "date"
);


--
-- Name: actual_visits; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW "app"."actual_visits" AS
 SELECT "chair_id",
    "doctor_id",
    "visit_date" AS "work_date",
    "accompanied_by",
    "load_date"
   FROM "app"."visits"
  WHERE ("visit_type" = 'actual'::"text");


--
-- Name: brands; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE "app"."brands" (
    "chair_id" bigint,
    "doctor_id" bigint,
    "brand_name" "text",
    "cm_prescribed_qty" double precision,
    "pm_prescribed_qty" double precision,
    "final_rcpa" double precision,
    "cm_target" double precision,
    "pm_target" double precision,
    "growth_booster" "text",
    "brand_priority" "text",
    "brand_rank" bigint,
    "load_date" "date"
);


--
-- Name: chemists; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE "app"."chemists" (
    "chair_id" bigint,
    "chemist_id" bigint,
    "doctor_id" bigint,
    "chemist_name" "text",
    "last_work_date" "date",
    "load_date" "date"
);


--
-- Name: data_vintage; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE "app"."data_vintage" (
    "table_name" "text",
    "max_load_date" "text",
    "row_count" bigint
);


--
-- Name: doctors; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE "app"."doctors" (
    "chair_id" bigint,
    "doctor_id" bigint,
    "doctor_name" "text",
    "specialty" "text",
    "clinic_name" "text",
    "city_name" "text",
    "mobile" "text",
    "avg_3_month_rcpa" double precision,
    "scientific_engagement" boolean,
    "patient_support" boolean,
    "avg_rcpa_national" double precision,
    "persona_prescriber" "text",
    "persona_type" "text",
    "persona_loyalty" "text",
    "persona_digital" "text",
    "load_date" "date",
    "name_norm" "text"
);


--
-- Name: doctor_codes; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW "app"."doctor_codes" AS
 SELECT DISTINCT "doctor_id",
    "avg_rcpa_national",
    "persona_prescriber",
    "persona_type",
    "persona_loyalty",
    "persona_digital"
   FROM "app"."doctors";


--
-- Name: hooks; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE "app"."hooks" (
    "chair_id" bigint,
    "doctor_id" bigint,
    "notes" "text",
    "hook_category" "text",
    "product_desc" "text",
    "work_date" "date",
    "load_date" "date"
);


--
-- Name: targets; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE "app"."targets" (
    "sbu_id" bigint,
    "cluster_name" "text",
    "performance_lower_limit" double precision,
    "performance_upper_limit" double precision,
    "mcr_threshold" double precision,
    "mvc_threshold" double precision,
    "load_date" "date"
);


--
-- Name: leaderboard_thresholds; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW "app"."leaderboard_thresholds" AS
 SELECT "sbu_id",
    "cluster_name",
    "performance_upper_limit",
    "performance_lower_limit"
   FROM "app"."targets";


--
-- Name: planned_visits; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW "app"."planned_visits" AS
 SELECT "chair_id",
    "doctor_id",
    "visit_date",
    "load_date"
   FROM "app"."visits"
  WHERE ("visit_type" = 'planned'::"text");


--
-- Name: rep_metrics; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE "app"."rep_metrics" (
    "chair_id" bigint,
    "month" bigint,
    "year" bigint,
    "no_of_doctors" bigint,
    "mcr_count" double precision,
    "mcr_coverage" double precision,
    "mv_frequency" double precision,
