    "load_date" "date"
);


--
-- Name: reps; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE "app"."reps" (
    "chair_id" bigint,
    "sbu_id" bigint,
    "rep_name" "text",
    "rep_code" bigint,
    "load_date" "date",
    "password_hash" "text"
);


--
-- Name: required_pending_visits; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE "app"."required_pending_visits" (
    "chair_id" bigint,
    "doctor_id" bigint,
    "year" bigint,
    "month" bigint,
    "number_of_visits" bigint,
    "visit_freq" "text",
    "required_visits" bigint,
    "visit_pending_this_month" bigint,
    "load_date" "date"
);


--
-- Name: thresholds; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW "app"."thresholds" AS
 SELECT DISTINCT "mcr_threshold",
    "mvc_threshold",
    "load_date"
   FROM "app"."targets";


